class Unit extends DataClass implements Insertable<Unit> {
  final int id;
  final int businessId;
  final String code;
  final String name;
  final String? symbol;

  /// Decimal places used when displaying quantities in this unit.
  final int decimalScale;
  final bool isActive;
  const Unit({
    required this.id,
    required this.businessId,
    required this.code,
    required this.name,
    this.symbol,
    required this.decimalScale,
    required this.isActive,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    map['business_id'] = Variable<int>(businessId);
    map['code'] = Variable<String>(code);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || symbol != null) {
      map['symbol'] = Variable<String>(symbol);
    }
    map['decimal_scale'] = Variable<int>(decimalScale);
    map['is_active'] = Variable<bool>(isActive);
    return map;
  }

  UnitsCompanion toCompanion(bool nullToAbsent) {
    return UnitsCompanion(
      id: Value(id),
      businessId: Value(businessId),
      code: Value(code),
      name: Value(name),
      symbol: symbol == null && nullToAbsent
          ? const Value.absent()
          : Value(symbol),
      decimalScale: Value(decimalScale),
      isActive: Value(isActive),
    );
  }

  factory Unit.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Unit(
      id: serializer.fromJson<int>(json['id']),
      businessId: serializer.fromJson<int>(json['businessId']),
      code: serializer.fromJson<String>(json['code']),
      name: serializer.fromJson<String>(json['name']),
      symbol: serializer.fromJson<String?>(json['symbol']),
      decimalScale: serializer.fromJson<int>(json['decimalScale']),
      isActive: serializer.fromJson<bool>(json['isActive']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<int>(id),
      'businessId': serializer.toJson<int>(businessId),
      'code': serializer.toJson<String>(code),
      'name': serializer.toJson<String>(name),
      'symbol': serializer.toJson<String?>(symbol),
      'decimalScale': serializer.toJson<int>(decimalScale),
      'isActive': serializer.toJson<bool>(isActive),
    };
  }

  Unit copyWith({
    int? id,
    int? businessId,
    String? code,
    String? name,
    Value<String?> symbol = const Value.absent(),
    int? decimalScale,
    bool? isActive,
  }) => Unit(
    id: id ?? this.id,
    businessId: businessId ?? this.businessId,
    code: code ?? this.code,
    name: name ?? this.name,
    symbol: symbol.present ? symbol.value : this.symbol,
    decimalScale: decimalScale ?? this.decimalScale,
    isActive: isActive ?? this.isActive,
  );
  Unit copyWithCompanion(UnitsCompanion data) {
    return Unit(
      id: data.id.present ? data.id.value : this.id,
      businessId: data.businessId.present
          ? data.businessId.value
          : this.businessId,
      code: data.code.present ? data.code.value : this.code,
      name: data.name.present ? data.name.value : this.name,
      symbol: data.symbol.present ? data.symbol.value : this.symbol,
      decimalScale: data.decimalScale.present
          ? data.decimalScale.value
          : this.decimalScale,
      isActive: data.isActive.present ? data.isActive.value : this.isActive,
    );
  }

  @override
  String toString() {
    return (StringBuffer('Unit(')
          ..write('id: $id, ')
          ..write('businessId: $businessId, ')
          ..write('code: $code, ')
          ..write('name: $name, ')
          ..write('symbol: $symbol, ')
          ..write('decimalScale: $decimalScale, ')
          ..write('isActive: $isActive')
          ..write(')'))
        .toString();
  }

  @override
  int get hashCode =>
      Object.hash(id, businessId, code, name, symbol, decimalScale, isActive);
  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      (other is Unit &&
          other.id == this.id &&
          other.businessId == this.businessId &&
          other.code == this.code &&
          other.name == this.name &&
          other.symbol == this.symbol &&
          other.decimalScale == this.decimalScale &&
          other.isActive == this.isActive);
}

