class Product extends DataClass implements Insertable<Product> {
  final int id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int businessId;
  final int? categoryId;
  final String name;
  final String? description;

  /// Nullable: many small sellers do not assign codes (D-021).
  final String? sku;
  final String? barcode;

  /// `goods`, `service`, `non_stock`.
  final String type;
  final String? photoPath;
  final String? videoPath;
  final int baseUnitId;

  /// Current weighted average cost per base unit in minor units (G-02).
  final int costPriceMinor;
  final int salePriceMinor;
  final int? wholesalePriceMinor;

  /// Cached stock balance in micro units — derived from movements (G-01).
  final int stockQuantityMicro;

  /// Low-stock threshold in micro units.
  final int minStockMicro;
  final int? maxStockMicro;
  final bool trackStock;

  /// Shipping attributes (grams / milliliters as integer units — D-021).
  final int? weightGrams;
  final int? volumeMl;
  final String? shippingNote;
  final String? marketplaceSkuTokopedia;
  final String? marketplaceSkuTiktok;
  final String? marketplaceSkuShopee;
  final String? notes;
  final bool isActive;
  final DateTime? archivedAt;
  const Product({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.businessId,
    this.categoryId,
    required this.name,
    this.description,
    this.sku,
    this.barcode,
    required this.type,
    this.photoPath,
    this.videoPath,
    required this.baseUnitId,
    required this.costPriceMinor,
    required this.salePriceMinor,
    this.wholesalePriceMinor,
    required this.stockQuantityMicro,
    required this.minStockMicro,
    this.maxStockMicro,
    required this.trackStock,
    this.weightGrams,
    this.volumeMl,
    this.shippingNote,
    this.marketplaceSkuTokopedia,
    this.marketplaceSkuTiktok,
    this.marketplaceSkuShopee,
    this.notes,
    required this.isActive,
    this.archivedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    {
      map['created_at'] = Variable<int>(
        $ProductsTable.$convertercreatedAt.toSql(createdAt),
      );
    }
    {
      map['updated_at'] = Variable<int>(
        $ProductsTable.$converterupdatedAt.toSql(updatedAt),
      );
    }
    map['business_id'] = Variable<int>(businessId);
