      map['category_id'] = Variable<int>(categoryId);
    }
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || description != null) {
      map['description'] = Variable<String>(description);
    }
    if (!nullToAbsent || sku != null) {
      map['sku'] = Variable<String>(sku);
    }
    if (!nullToAbsent || barcode != null) {
      map['barcode'] = Variable<String>(barcode);
    }
    map['type'] = Variable<String>(type);
    if (!nullToAbsent || photoPath != null) {
      map['photo_path'] = Variable<String>(photoPath);
    }
    if (!nullToAbsent || videoPath != null) {
      map['video_path'] = Variable<String>(videoPath);
    }
    map['base_unit_id'] = Variable<int>(baseUnitId);
    map['cost_price_minor'] = Variable<int>(costPriceMinor);
    map['sale_price_minor'] = Variable<int>(salePriceMinor);
    if (!nullToAbsent || wholesalePriceMinor != null) {
      map['wholesale_price_minor'] = Variable<int>(wholesalePriceMinor);
    }
    map['stock_quantity_micro'] = Variable<int>(stockQuantityMicro);
    map['min_stock_micro'] = Variable<int>(minStockMicro);
    if (!nullToAbsent || maxStockMicro != null) {
      map['max_stock_micro'] = Variable<int>(maxStockMicro);
    }
    map['track_stock'] = Variable<bool>(trackStock);
    if (!nullToAbsent || weightGrams != null) {
      map['weight_grams'] = Variable<int>(weightGrams);
    }
    if (!nullToAbsent || volumeMl != null) {
      map['volume_ml'] = Variable<int>(volumeMl);
    }
    if (!nullToAbsent || shippingNote != null) {
      map['shipping_note'] = Variable<String>(shippingNote);
    }
    if (!nullToAbsent || marketplaceSkuTokopedia != null) {
      map['marketplace_sku_tokopedia'] = Variable<String>(
        marketplaceSkuTokopedia,
      );
    }
    if (!nullToAbsent || marketplaceSkuTiktok != null) {
      map['marketplace_sku_tiktok'] = Variable<String>(marketplaceSkuTiktok);
    }
    if (!nullToAbsent || marketplaceSkuShopee != null) {
      map['marketplace_sku_shopee'] = Variable<String>(marketplaceSkuShopee);
    }
    if (!nullToAbsent || notes != null) {
      map['notes'] = Variable<String>(notes);
    }
    map['is_active'] = Variable<bool>(isActive);
    if (!nullToAbsent || archivedAt != null) {
      map['archived_at'] = Variable<int>(
        $ProductsTable.$converterarchivedAtn.toSql(archivedAt),
      );
    }
    return map;
  }

