class Purchase extends DataClass implements Insertable<Purchase> {
  final int id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final int businessId;
  final int? supplierId;
  final String? number;

  /// `draft`, `finalized`, `voided`.
  final String status;
  final int subtotalMinor;
  final int discountTotalMinor;
  final int taxTotalMinor;

  /// Additional purchase costs (freight etc.) allocated into WAC.
  final int otherCostMinor;
  final int grandTotalMinor;
  final int paidTotalMinor;
  final int dueTotalMinor;
  final String? note;
  final DateTime? finalizedAt;
  final DateTime? voidedAt;
  const Purchase({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    required this.businessId,
    this.supplierId,
    this.number,
    required this.status,
    required this.subtotalMinor,
    required this.discountTotalMinor,
    required this.taxTotalMinor,
    required this.otherCostMinor,
    required this.grandTotalMinor,
    required this.paidTotalMinor,
    required this.dueTotalMinor,
    this.note,
    this.finalizedAt,
    this.voidedAt,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<int>(id);
    {
      map['created_at'] = Variable<int>(
        $PurchasesTable.$convertercreatedAt.toSql(createdAt),
      );
    }
    {
      map['updated_at'] = Variable<int>(
        $PurchasesTable.$converterupdatedAt.toSql(updatedAt),
      );
    }
    map['business_id'] = Variable<int>(businessId);
    if (!nullToAbsent || supplierId != null) {
      map['supplier_id'] = Variable<int>(supplierId);
    }
    if (!nullToAbsent || number != null) {
      map['number'] = Variable<String>(number);
    }
    map['status'] = Variable<String>(status);
    map['subtotal_minor'] = Variable<int>(subtotalMinor);
    map['discount_total_minor'] = Variable<int>(discountTotalMinor);
    map['tax_total_minor'] = Variable<int>(taxTotalMinor);
    map['other_cost_minor'] = Variable<int>(otherCostMinor);
    map['grand_total_minor'] = Variable<int>(grandTotalMinor);
    map['paid_total_minor'] = Variable<int>(paidTotalMinor);
    map['due_total_minor'] = Variable<int>(dueTotalMinor);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    if (!nullToAbsent || finalizedAt != null) {
      map['finalized_at'] = Variable<int>(
        $PurchasesTable.$converterfinalizedAtn.toSql(finalizedAt),
      );
    }
    if (!nullToAbsent || voidedAt != null) {
      map['voided_at'] = Variable<int>(
        $PurchasesTable.$convertervoidedAtn.toSql(voidedAt),
      );
    }
    return map;
  }

  PurchasesCompanion toCompanion(bool nullToAbsent) {
    return PurchasesCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      businessId: Value(businessId),
      supplierId: supplierId == null && nullToAbsent
          ? const Value.absent()
          : Value(supplierId),
      number: number == null && nullToAbsent
          ? const Value.absent()
          : Value(number),
      status: Value(status),
      subtotalMinor: Value(subtotalMinor),
      discountTotalMinor: Value(discountTotalMinor),
      taxTotalMinor: Value(taxTotalMinor),
      otherCostMinor: Value(otherCostMinor),
      grandTotalMinor: Value(grandTotalMinor),
      paidTotalMinor: Value(paidTotalMinor),
      dueTotalMinor: Value(dueTotalMinor),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
      finalizedAt: finalizedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(finalizedAt),
      voidedAt: voidedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(voidedAt),
    );
  }

  factory Purchase.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Purchase(
      id: serializer.fromJson<int>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      businessId: serializer.fromJson<int>(json['businessId']),
      supplierId: serializer.fromJson<int?>(json['supplierId']),
      number: serializer.fromJson<String?>(json['number']),
      status: serializer.fromJson<String>(json['status']),
      subtotalMinor: serializer.fromJson<int>(json['subtotalMinor']),
      discountTotalMinor: serializer.fromJson<int>(json['discountTotalMinor']),
      taxTotalMinor: serializer.fromJson<int>(json['taxTotalMinor']),
