    number: number.present ? number.value : this.number,
    status: status ?? this.status,
    subtotalMinor: subtotalMinor ?? this.subtotalMinor,
    discountTotalMinor: discountTotalMinor ?? this.discountTotalMinor,
    taxTotalMinor: taxTotalMinor ?? this.taxTotalMinor,
    otherCostMinor: otherCostMinor ?? this.otherCostMinor,
    grandTotalMinor: grandTotalMinor ?? this.grandTotalMinor,
    paidTotalMinor: paidTotalMinor ?? this.paidTotalMinor,
    dueTotalMinor: dueTotalMinor ?? this.dueTotalMinor,
    note: note.present ? note.value : this.note,
    finalizedAt: finalizedAt.present ? finalizedAt.value : this.finalizedAt,
    voidedAt: voidedAt.present ? voidedAt.value : this.voidedAt,
  );
  Purchase copyWithCompanion(PurchasesCompanion data) {
    return Purchase(
      id: data.id.present ? data.id.value : this.id,
      createdAt: data.createdAt.present ? data.createdAt.value : this.createdAt,
      updatedAt: data.updatedAt.present ? data.updatedAt.value : this.updatedAt,
      businessId: data.businessId.present
          ? data.businessId.value
          : this.businessId,
      supplierId: data.supplierId.present
          ? data.supplierId.value
