      grandTotalMinor: data.grandTotalMinor.present
          ? data.grandTotalMinor.value
          : this.grandTotalMinor,
      paidTotalMinor: data.paidTotalMinor.present
          ? data.paidTotalMinor.value
          : this.paidTotalMinor,
      dueTotalMinor: data.dueTotalMinor.present
