    map['direction'] = Variable<String>(direction);
    map['purpose'] = Variable<String>(purpose);
    if (!nullToAbsent || accountId != null) {
      map['account_id'] = Variable<int>(accountId);
    }
    if (!nullToAbsent || counterAccountId != null) {
      map['counter_account_id'] = Variable<int>(counterAccountId);
    }
    if (!nullToAbsent || saleId != null) {
      map['sale_id'] = Variable<int>(saleId);
    }
    if (!nullToAbsent || purchaseId != null) {
      map['purchase_id'] = Variable<int>(purchaseId);
    }
    if (!nullToAbsent || refundOfPaymentId != null) {
      map['refund_of_payment_id'] = Variable<int>(refundOfPaymentId);
    }
    map['amount_minor'] = Variable<int>(amountMinor);
    map['method'] = Variable<String>(method);
    if (!nullToAbsent || category != null) {
      map['category'] = Variable<String>(category);
    }
    if (!nullToAbsent || referenceNumber != null) {
      map['reference_number'] = Variable<String>(referenceNumber);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    {
      map['paid_at'] = Variable<int>(
        $PaymentsTable.$converterpaidAt.toSql(paidAt),
      );
    }
    return map;
  }

  PaymentsCompanion toCompanion(bool nullToAbsent) {
    return PaymentsCompanion(
      id: Value(id),
      businessId: Value(businessId),
      direction: Value(direction),
      purpose: Value(purpose),
